CREATE TABLE IF NOT EXISTS saliyah_sim_companies (id TEXT PRIMARY KEY,founder_id TEXT NOT NULL,name TEXT NOT NULL,activity TEXT NOT NULL,location TEXT NOT NULL,description TEXT NOT NULL,capital INTEGER NOT NULL,status TEXT NOT NULL DEFAULT 'pending_human' CHECK(status IN ('pending_human','approved','rejected')),reviewed_by TEXT,reviewed_at TEXT,created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP); CREATE TABLE IF NOT EXISTS saliyah_sim_jobs (id TEXT PRIMARY KEY,company_id TEXT NOT NULL REFERENCES saliyah_sim_companies(id),title TEXT NOT NULL,salary INTEGER NOT NULL,status TEXT NOT NULL DEFAULT 'open',created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP)